(function lifeGame(canvasId) {
    // Constants
    const canvasSize = 500;
    const cellSize = 10;
    const cols = canvasSize / cellSize;
    const rows = canvasSize / cellSize;
    const fadeFrames = 20; // frames to fade out dying cells

    // Create container
    const container = document.createElement('div');
    container.style.display = 'flex';
    container.style.flexDirection = 'column';
    container.style.alignItems = 'center';
    container.style.width = canvasSize + 'px';
    container.style.margin = '20px auto';

    // Create UI elements
    const ui = document.createElement('div');
    ui.style.marginBottom = '10px';

    const patternSelect = document.createElement('select');
    const patterns = ['Glider', 'Blinker', 'Gosper Gun', 'Pulsar'];
    patterns.forEach(p => {
        const opt = document.createElement('option');
        opt.value = p;
        opt.text = p;
        patternSelect.appendChild(opt);
    });

    const applyBtn = document.createElement('button');
    applyBtn.textContent = 'Apply Pattern';

    const randomBtn = document.createElement('button');
    randomBtn.textContent = 'Randomize';

    const clearBtn = document.createElement('button');
    clearBtn.textContent = 'Clear';

    const speedLabel = document.createElement('label');
    speedLabel.textContent = 'Speed: 5 gen/sec';

    const speedSlider = document.createElement('input');
    speedSlider.type = 'range';
    speedSlider.min = '1';
    speedSlider.max = '10';
    speedSlider.value = '5';

    ui.appendChild(patternSelect);
    ui.appendChild(applyBtn);
    ui.appendChild(randomBtn);
    ui.appendChild(clearBtn);
    ui.appendChild(speedLabel);
    ui.appendChild(speedSlider);

    // Create canvas
    const canvas = document.getElementById(canvasId);
    if (!canvas) {
        console.error('Canvas not found');
        return;
    }
    canvas.width = canvasSize;
    canvas.height = canvasSize;
    const ctx = canvas.getContext('2d');
    ctx.font = cellSize + 'px Arial';
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'center';

    container.insertBefore(ui, canvas);
    document.body.appendChild(container);

    // Cell data arrays
    const alive = new Uint8Array(rows * cols);
    const age = new Uint8Array(rows * cols);
    const dying = new Uint8Array(rows * cols); // 0: alive, 1: dying
    const dieTimer = new Uint8Array(rows * cols); // counts frames of fade

    // Emoji mapping based on age
    const emojis = ['🟢', '🟡', '🟠', '🔴', '❌'];
    const ageThreshold = [0, 2, 5, 8]; // thresholds for emoji indices

    // Patterns data
    const patternData = {
        'Glider': [[1,0],[2,1],[0,2],[1,2],[2,2]],
        'Blinker': [[1,0],[1,1],[1,2]],
        'Gosper Gun': [
            [1,5],[2,5],[1,6],[2,6],[11,5],[12,5],[11,6],[12,6],[11,7],[12,7],[13,6],
            [21,5],[22,5],[21,6],[22,6],[21,7],[22,7],[21,8],[22,8],[23,9],[21,10],[23,10],
            [25,1],[25,2],[24,3],[25,3],[26,3],[27,3],[26,4],[24,5],[25,5],[26,5],[27,2],[27,7],
            [24,9],[25,9],[26,9],[27,10],[25,11]
        ],
        'Pulsar': [
            [3,2],[3,3],[3,4],[6,2],[6,3],[6,4],[3,6],[3,7],[3,8],[6,6],[6,7],[6,8],
            [8,3],[8,4],[8,5],[9,3],[9,4],[9,5],[8,6],[8,7],[8,8],[11,3],[11,4],[11,5],
            [12,3],[12,4],[12,5],[11,6],[11,7],[11,8],
            [13,2],[13,3],[13,4],[16,2],[16,3],[16,4],
            [13,6],[13,7],[13,8],[16,6],[16,7],[16,8],
            [13,10],[13,11],[13,12],[16,10],[16,11],[16,12]
        ]
    };

    // Helper to place pattern at center
    function applyPattern(name) {
        clearGrid();
        const cells = patternData[name];
        const offsetRow = Math.floor(rows / 2 - 5);
        const offsetCol = Math.floor(cols / 2 - 5);
        cells.forEach(([dr, dc]) => {
            const r = offsetRow + dr;
            const c = offsetCol + dc;
            if (r >= 0 && r < rows && c >= 0 && c < cols) {
                const idx = r * cols + c;
                alive[idx] = 1;
                age[idx] = 0;
                dying[idx] = 0;
                dieTimer[idx] = 0;
            }
        });
    }

    // Clear grid
    function clearGrid() {
        alive.fill(0);
        age.fill(0);
        dying.fill(0);
        dieTimer.fill(0);
    }

    // Randomize grid
    function randomizeGrid() {
        for (let i = 0; i < alive.length; i++) {
            alive[i] = Math.random() < 0.5 ? 1 : 0;
            age[i] = 0;
            dying[i] = 0;
            dieTimer[i] = 0;
        }
    }

    // Toggle cell on click
    canvas.addEventListener('click', function (e) {
        const rect = canvas.getBoundingClientRect();
        const x = Math.floor((e.clientX - rect.left) / cellSize);
        const y = Math.floor((e.clientY - rect.top) / cellSize);
        if (x < 0 || x >= cols || y < 0 || y >= rows) return;
        const idx = y * cols + x;
        alive[idx] = alive[idx] ? 0 : 1;
        age[idx] = 0;
        dying[idx] = 0;
        dieTimer[idx] = 0;
    });

    // Generation logic
    function step() {
        const newAlive = new Uint8Array(alive.length);
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                const idx = r * cols + c;
                let neighbors = 0;
                for (let dr = -1; dr <= 1; dr++) {
                    for (let dc = -1; dc <= 1; dc++) {
                        if (dr === 0 && dc === 0) continue;
                        const nr = (r + dr + rows) % rows;
                        const nc = (c + dc + cols) % cols;
                        const nidx = nr * cols + nc;
                        neighbors += alive[nidx];
                    }
                }
                if (alive[idx]) {
                    if (neighbors < 2 || neighbors > 3) {
                        newAlive[idx] = 0; // will die
                    } else {
                        newAlive[idx] = 1; // stay alive
                    }
                } else {
                    if (neighbors === 3) {
                        newAlive[idx] = 1; // born
                    }
                }
            }
        }
        // Update states
        for (let i = 0; i < alive.length; i++) {
            if (alive[i] && newAlive[i] === 0) {
                dying[i] = 1;
                dieTimer[i] = 0;
            } else if (!alive[i] && newAlive[i] === 1) {
                // birth
            }
        }
        alive.set(newAlive);
        for (let i = 0; i < alive.length; i++) {
            if (alive[i]) {
                age[i] = (age[i] + 1) % 64; // keep small
            } else {
                age[i] = 0;
            }
            if (dying[i]) {
                dieTimer[i]++;
                if (dieTimer[i] >= fadeFrames) dying[i] = 0;
            }
        }
    }

    // Draw grid
    function draw() {
        ctx.clearRect(0, 0, canvasSize, canvasSize);
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                const idx = r * cols + c;
                const isAlive = alive[idx];
                let alpha = 1;
                if (dying[idx]) {
                    alpha = 1 - dieTimer[idx] / fadeFrames;
                }
                if (isAlive && !dying[idx]) {
                    let emojiIndex = 0;
                    if (age[idx] >= ageThreshold[3]) emojiIndex = 3;
                    else if (age[idx] >= ageThreshold[2]) emojiIndex = 2;
                    else if (age[idx] >= ageThreshold[1]) emojiIndex = 1;
                    else emojiIndex = 0;
                    ctx.globalAlpha = alpha;
                    ctx.fillText(emojis[emojiIndex], c * cellSize + cellSize / 2, r * cellSize + cellSize / 2);
                }
            }
        }
        ctx.globalAlpha = 1;
    }

    // Animation loop
    let lastStep = 0;
    let speed = Number(speedSlider.value);
    function loop(timestamp) {
        if (timestamp - lastStep >= 1000 / speed) {
            step();
            lastStep = timestamp;
        }
        draw();
        requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);

    // UI event handlers
    applyBtn.addEventListener('click', () => applyPattern(patternSelect.value));
    randomBtn.addEventListener('click', randomizeGrid);
    clearBtn.addEventListener('click', clearGrid);
    speedSlider.addEventListener('input', () => {
        speed = Number(speedSlider.value);
        speedLabel.textContent = 'Speed: ' + speed + ' gen/sec';
    });
});)();
